-- =============================================================================
-- V1.56__seed_qa_sports_outdoor.sql
-- =============================================================================
-- 功能: 为 AI 客服学习知识库 (ai_cs_learned_kb) 填充"运动户外"一级分类
--       (sports_outdoor) 下 5 个二级分类的高价值 Q&A 种子数据。
--
-- 数据规模: 5 个二级分类 x 30 条 = 150 条 Q&A
--   1. sports_equipment     - 运动器材 (哑铃/跑步机/瑜伽/健身/杠铃/拉力器)
--   2. sports_outdoor_gear  - 户外装备 (帐篷/睡袋/登山/背包/炉具/登山杖)
--   3. sports_apparel       - 运动服饰 (运动服/速干衣/运动裤/运动文胸/瑜伽服)
--   4. sports_cycling       - 骑行装备 (自行车/电动车/头盔/骑行服/车灯/车锁)
--   5. sports_fishing       - 垂钓用品 (鱼竿/鱼线/鱼饵/鱼钩/渔轮/钓箱)
--
-- Q&A 覆盖场景: 器材成色、使用次数、是否原装、配件齐全、保修、适合人群、
--               使用方法、保养、价格谈判等真实闲鱼运动户外买卖场景。
--
-- 幂等性说明: content_hash = MD5(question+answer), 唯一键 uk_learned_kb_hash
--             保证同一 (question, answer) 不会重复插入。
--
-- 依赖: ai_cs_kb_category 表中需已存在上述 5 个二级分类 code，且
--       parent_id 非空 (即挂载在 sports_outdoor 一级分类下)。
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. sports_equipment - 运动器材 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.56', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'sports_equipment' AS code, '哑铃用了多久？成色怎么样？' AS question, '亲，这副哑铃是去年618在京东买的，在家用了大概半年，每周练3到4次。成色9成新，把手防滑纹路保存很好，没有磕碰掉漆。是可调节款，从2kg到24kg，现在搬家带不走所以转让。拍了各角度细节图您可以看看，真心成色不错，买到就是赚到，支持验货再确认收货哦。' AS answer, '哑铃,成色,可调节,健身,家用' AS tags, '哑铃成色与使用情况说明' AS source_summary, 88 AS score
  UNION ALL SELECT 'sports_equipment', '跑步机用了多少小时？马达还行吗？', '亲好，这台跑步机买了两年，累计使用约300小时，主要是我妈晨跑用。马达状态很好，跑带去年刚换过新的，运行平稳没异响。显示屏功能正常，心率监测也准。最大承重120kg，适合家用。因为换了大房子有专门健身区才出，保养得很好您放心，欢迎上门验机。', '跑步机,使用时长,保养,马达,家用', '跑步机使用时长与保养状况', 90
  UNION ALL SELECT 'sports_equipment', '瑜伽垫是什么材质？多厚？防滑吗？', '亲，这款是TPE材质的瑜伽垫，8mm加厚款，回弹性很好，对膝盖保护到位。双面都有防滑纹理，出汗也不打滑，我练流瑜伽半年完全没问题。垫子没有异味，TPE比PVC环保很多。原价168买的，用了半年成色9新，卷起来不占地方。送您一个绑带方便携带。', '瑜伽垫,TPE,防滑,加厚,环保', '瑜伽垫材质厚度与防滑性能', 85
  UNION ALL SELECT 'sports_equipment', '杠铃片是原装的吗？有没有磕碰？', '亲，杠铃片是原装的，当时跟杠铃杆一起在迪卡侬买的，有购买记录可以发您看。包胶片没有掉胶，边缘有一两处轻微磕碰是正常使用痕迹，不影响使用。总共20kg两片、10kg两片、5kg两片，一共70kg。孔径标准28mm，通用杠铃杆都能用。真心诚意出，成色对得起价格。', '杠铃片,原装,包胶,迪卡侬,成色', '杠铃片原装与成色说明', 87
  UNION ALL SELECT 'sports_equipment', '拉力器配件齐全吗？门锚和把手都有吗？', '亲，配件齐全的，包括门锚、泡沫把手、脚踝绑带、收纳包都在，说明书也在。这是五管可调节阻力款，10到50磅五档调节，练背练手臂都很好用。把手泡沫没有破损，弹簧弹力正常没松弛。用了大概四个月，因为办了健身房卡所以闲置了。成色9.5新，几乎全新。', '拉力器,配件,可调节,阻力,门锚', '拉力器配件齐全与使用情况', 86
  UNION ALL SELECT 'sports_equipment', '哑铃还在保修期内吗？有发票吗？', '亲，哑铃是去年9月买的，京东自营有电子发票我可以截图发您。品牌保修一年，现在还在保修期内。不过哑铃这种东西基本不会坏，我家用的很爱惜没有摔过。把手螺纹完好，配重块旋转顺畅没有卡顿。如果您需要发票凭证我可以一起发给您，放心购买。', '哑铃,保修,发票,京东,凭证', '哑铃保修期与发票凭证', 84
  UNION ALL SELECT 'sports_equipment', '这台跑步机我80kg能用吗？跑起来稳吗？', '亲，完全没问题的，这台跑步机最大承重120kg，您80kg非常轻松。我自己75kg跑了一年多很稳，跑台够宽敞，扶手也结实。有减震系统对膝盖友好，楼下也不容易听到噪音。坡度可调0到15档，速度最高16km每小时，快走慢跑冲刺都行。适合全家用的好机器，真心推荐。', '跑步机,承重,减震,坡度,家用', '跑步机承重与稳定性说明', 89
  UNION ALL SELECT 'sports_equipment', '瑜伽砖怎么用？初学者适合吗？', '亲，瑜伽砖特别适合初学者辅助练习，可以垫手垫腰降低动作难度。这款是高密度EVA材质，硬度够支撑力强，不像便宜货会软塌。两块一起用，练三角式、半月式的时候垫手特别有帮助。我刚开始练瑜伽就靠它过渡，现在能独立完成就转让了。成色9新，边角有轻微使用痕。', '瑜伽砖,EVA,初学者,辅助,高密度', '瑜伽砖使用方法与适用人群', 82
  UNION ALL SELECT 'sports_equipment', '健身车骑起来有异响吗？怎么保养的？', '亲，没有异响的，这台动感单车我每周保养一次，链条定期上油，脚踏轴承状态良好。磁控阻力调节顺滑没有卡顿感。坐垫是加厚凝胶款，长时间骑也不硌。电子表显示正常，能记录里程速度消耗卡路里。买了两年使用约200小时，因为膝盖受伤医生建议改游泳才出。', '健身车,保养,异响,磁控,动感单车', '健身车保养状况与使用情况', 88
  UNION ALL SELECT 'sports_equipment', '哑铃还能便宜点吗？诚心要的。', '亲，这副哑铃原价368买的，用了半年成色9新，现在标价150已经很实在了。可调节2到24kg，相当于买了一套哑铃，算下来很划算。如果您诚心要，140包快递给您，到货验货满意再确认。哑铃这种东西耐造不会坏，用个十年八年没问题，这个价格真的性价比很高了。', '哑铃,价格,可调节,性价比,包邮', '哑铃价格谈判与性价比说明', 86
  UNION ALL SELECT 'sports_equipment', '跑步机噪音大吗？住楼房会影响楼下吗？', '亲，这台跑步机有六点减震系统，底部还配了减震垫，噪音控制得很好。我自己住楼房用了两年，楼下从没投诉过。跑带是静音款，马达也是静音电机，正常慢跑大概50分贝左右，跟正常说话声差不多。建议您放在客厅靠墙位置，再铺一层地毯效果更好。晚上9点后用完全没问题。', '跑步机,噪音,减震,静音,楼房', '跑步机噪音与减震性能说明', 87
  UNION ALL SELECT 'sports_equipment', '瑜伽球能承重多少？我70kg坐上去会爆吗？', '亲，放心用，这款瑜伽球是防爆PVC材质，承重300kg没问题，70kg完全轻松。它不是普通气球那种，扎破了也只会慢慢漏气不会爆，安全性很好。我130斤的朋友天天坐上面办公都没事。送一个打气筒，充气很方便。直径65cm适合身高160到175cm，成色9新，表面无划痕。', '瑜伽球,承重,防爆,PVC,安全', '瑜伽球承重与安全性说明', 83
  UNION ALL SELECT 'sports_equipment', '杠铃杆是什么规格？多长？能承重多少？', '亲，这是标准奥林匹克杠铃杆，长度2.2米，重量20kg，承重1500磅没问题。滚花防滑处理很好，握感舒服不磨手。轴承旋转顺畅，做抓举挺举都顺。原价800多买的，用了两年成色8.5新，滚花处有轻微磨损但不影响抓握。适合健身进阶玩家，商业健身房级别的品质。', '杠铃杆,奥林匹克,规格,承重,滚花', '杠铃杆规格与承重说明', 89
  UNION ALL SELECT 'sports_equipment', '拉力器阻力怎么调节？适合女生用吗？', '亲，这款是五管可调节的，把弹簧增减就能调阻力，10到50磅五档，女生从最轻档开始完全没问题。我女朋友也用它练手臂和背部，慢慢加阻力循序渐进。把手是泡沫包裹的，握着不勒手。门锚装在门框上就能练，不伤门框。收纳包装着放抽屉里也不占地方，家用很方便。', '拉力器,阻力调节,女生,可调节,家用', '拉力器阻力调节与适用人群', 84
  UNION ALL SELECT 'sports_equipment', '哑铃邮寄吗？快递费多少？怕摔坏吗？', '亲，哑铃可以邮寄的，我会用气泡膜包好再装纸箱，加填充物防震，不会摔坏。可调节款拆开分件包装，重量轻一些运费也便宜。顺丰陆运大概30到40元，包邮的话我用中通更实惠。支持到货验货，有问题拒收退回就行。如果同城也可以面交，地铁站碰面最方便。', '哑铃,邮寄,包装,快递,面交', '哑铃邮寄与包装方式说明', 81
  UNION ALL SELECT 'sports_equipment', '跑步机能折叠吗？占地面积多大？', '亲，这台跑步机是折叠款的，跑台可以竖起来收纳，折叠后占地面积只有0.5平米，放阳台角落很省空间。展开后跑台尺寸130乘45cm，跑起来够宽敞。有液压缓降功能，放下跑台不会突然砸下去，对女生很友好。底部有滚轮，移动也方便。适合小户型家用的好选择。', '跑步机,折叠,收纳,省空间,液压', '跑步机折叠与占地面积说明', 86
  UNION ALL SELECT 'sports_equipment', '瑜伽垫防滑效果好吗？出汗会打滑吗？', '亲，这款瑜伽垫双面都有防滑纹理，正面是波浪纹防滑，背面是点状纹抓地。我练热瑜伽出汗很多，完全不打滑，抓地力比普通垫子强很多。TPE材质本身也有一定粘性，在木地板和瓷砖上都不跑垫。用了半年防滑效果没有衰减。送瑜伽绑带一条，卷起来携带方便。', '瑜伽垫,防滑,出汗,TPE,抓地', '瑜伽垫防滑与出汗表现说明', 83
  UNION ALL SELECT 'sports_equipment', '这套健身器材含健身椅吗？椅子能调节吗？', '亲，这套包含可调节健身椅的，椅背可以调5个角度，从平躺到上斜90度都能调，做卧推、坐姿推举、飞鸟都很稳。椅子是加厚海绵垫，承重150kg不晃。框架是加厚钢管，焊点牢固。整套含哑铃架、哑铃、健身椅，一站式中度家用够了。成色8.5新，使用痕迹正常。', '健身椅,可调节,卧推,承重,套装', '健身椅调节与套装配置说明', 88
  UNION ALL SELECT 'sports_equipment', '哑铃有点生锈了还能用吗？怎么处理？', '亲，这副哑铃是铸铁包胶的，把手处有轻微锈迹是因为放阳台受潮了，不影响使用。我已经用砂纸打磨过，再涂了一层防锈油，现在看起来很干净。包胶部分完好没有掉胶。铸铁哑铃耐用得很，这点锈完全不影响，价格已经按成色让步了，性价比很高。建议您放干燥处保存就行。', '哑铃,生锈,包胶,铸铁,保养', '哑铃生锈处理与保养建议', 79
  UNION ALL SELECT 'sports_equipment', '跑步机坡度调节好用吗？最大多少度？', '亲，坡度电动调节很顺滑，0到15档一键调节，最大大概15度坡度，模拟爬坡效果很好。爬坡模式燃脂效率比平跑高很多，我减肥期天天爬坡走30分钟，两个月瘦了8斤。坡度和速度可以组合12种程序模式，减脂、心肺、间歇训练都有。程序自动调节，跟着跑就行很省心。', '跑步机,坡度,电动调节,燃脂,程序', '跑步机坡度调节与训练模式', 87
  UNION ALL SELECT 'sports_equipment', '瑜伽带是做什么用的？怎么使用？', '亲，瑜伽带是辅助拉伸的工具，特别适合柔韧性不好的朋友。练坐姿前屈的时候脚勾不到，就用带子套脚上拉。束角式、牛面式这些需要手在背后相扣的动作，用带子做过渡特别有用。这款是棉质带子，金属扣调节长度，结实耐用不会滑。成色9新，几乎没用过，送瑜伽砖一起。', '瑜伽带,拉伸,辅助,柔韧性,棉质', '瑜伽带用途与使用方法说明', 80
  UNION ALL SELECT 'sports_equipment', '杠铃有锈迹正常吗？会影响使用吗？', '亲，杠铃杆滚花处有轻微锈迹是正常的，健身房里的杠铃用久了都会有。这是因为手汗和空气接触氧化，不影响结构和承重。我已经用钢丝刷清理过，涂了防锈油，看起来干净多了。真正影响使用的是弯曲变形，这根杆子我放过水平仪测过，笔直没有变形。价格已按成色让步。', '杠铃,锈迹,滚花,防锈,变形', '杠铃锈迹处理与使用影响说明', 78
  UNION ALL SELECT 'sports_equipment', '拉力器弹簧会松吗？用了多久弹力还行吗？', '亲，这款拉力器用的是天然橡胶弹簧，用了四个月弹力依然很好，没有松弛。跟廉价钢丝弹簧不同，橡胶弹簧耐用且不易断。我每次用完都擦拭干净放收纳包，避免暴晒和高温，这样能延长寿命。五根弹簧可以自由组合阻力，从10到50磅。成色9.5新，真心几乎全新。', '拉力器,弹簧,弹力,橡胶,耐用', '拉力器弹簧弹力与耐用性说明', 83
  UNION ALL SELECT 'sports_equipment', '哑铃重量准确吗？跟标称一致吗？', '亲，重量准确的，我用厨房秤逐个称过，跟标称误差在2%以内，这在哑铃里算很精准了。可调节款每个配重片都有标重，2kg、1kg、0.5kg组合很灵活。把手本身1.5kg，全套最多24kg。精度比健身房那种地摊货好很多。如果您有秤到手可以复称，不准包退。', '哑铃,重量,精准,可调节,误差', '哑铃重量准确性与标称说明', 85
  UNION ALL SELECT 'sports_equipment', '跑步机马达多少匹？持续功率够吗？', '亲，这台跑步机马达是2.5匹持续功率，峰值4匹，家用完全够。我80kg的朋友跑16km每小时冲刺都没问题，马达不发热不衰减。跟那些1匹的廉价跑步机完全不是一个级别，跑起来稳如泰山。马达有五年质保，现在用了两年没出过任何问题。静音效果也好，晚上跑不扰民。', '跑步机,马达,功率,持续,静音', '跑步机马达功率与性能说明', 90
  UNION ALL SELECT 'sports_equipment', '瑜伽垫有气味吗？新买的会不会很刺鼻？', '亲，这款TPE瑜伽垫几乎没气味，刚拆开有淡淡橡胶味，通风放一天就散了。跟PVC垫子那种刺鼻塑料味完全不同，TPE是环保材料不含增塑剂，对身体无害。我用了半年现在完全没味道了。如果到手觉得有味道，用湿布擦一下放通风处半天就好。成色9新，无破损无掉渣。', '瑜伽垫,气味,TPE,环保,无味', '瑜伽垫气味与材质安全性说明', 82
  UNION ALL SELECT 'sports_equipment', '健身椅调节顺滑吗？会不会晃？', '亲，健身椅调节很顺滑，卡扣是弹簧钢的，每档到位有清脆的咔嗒声，不会虚位。椅子框架是加厚2mm方管，焊缝满焊处理，我90kg的朋友躺上面做卧推完全稳，不晃不响。海绵垫是高密度回弹海绵，用了两年没塌陷。底座有防滑脚垫，在光滑地面也不跑。成色8.5新。', '健身椅,调节,稳固,卧推,卡扣', '健身椅调节与稳固性说明', 86
  UNION ALL SELECT 'sports_equipment', '哑铃把手磨损严重吗？防滑还好吗？', '亲，把手成色很好，防滑纹路清晰可见。我每次用都戴健身手套，所以把手没有直接摩擦，磨损很轻。铸铁把手中段有滚花防滑，即使出汗也握得住。配重块旋转螺纹顺畅，没有滑丝。整副哑铃成色9新，只有配重块边缘有轻微使用痕。原价368，现在150出，性价比很高。', '哑铃,把手,防滑,磨损,成色', '哑铃把手磨损与防滑状况', 84
  UNION ALL SELECT 'sports_equipment', '跑步机显示屏正常吗？功能都能用吗？', '亲，显示屏完全正常，蓝光LCD屏字迹清晰。能显示速度、距离、时间、卡路里、心率、坡度，功能都正常。手握心率传感器灵敏，数据跟手环对比过很准。有5个快捷程序和3个用户自定义程序，跟着程序跑很方便。音响接口能连手机放音乐，音质还行。用了两年一切正常。', '跑步机,显示屏,心率,程序,正常', '跑步机显示屏功能与使用状况', 88
  UNION ALL SELECT 'sports_equipment', '这套瑜伽套装含什么？适合初学者吗？', '亲，这套瑜伽套装含垫子、两块砖、一条拉伸带、一个收纳包，初学者一站式配齐。垫子是8mm加厚TPE款，防滑回弹好。砖是高密度EVA，辅助到位。拉伸带棉质带金属扣，结实耐用。我报了瑜伽班老师要求买的，学完一期就没练了，成色9新几乎全新。原价268整套，现在120出。', '瑜伽套装,初学者,垫子,瑜伽砖,拉伸带', '瑜伽套装配置与初学者适用说明', 85
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 2. sports_outdoor_gear - 户外装备 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.56', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'sports_outdoor_gear' AS code, '这个帐篷防水吗？下大雨会漏吗？' AS question, '亲，这款是牧高笛冷山2代，耐水压3000mm，下大雨完全没问题。我去年在四姑娘山遇到暴雨，帐篷里一点没漏，缝线都做了压胶处理。外账是涤纶PU涂层，地面是防水PE底，再配个地布更稳当。双人双层款，透气防结露，早上起来内帐不会湿。成色9新，用了3次，全套含地钉风绳收纳袋。' AS answer, '帐篷,防水,牧高笛,双层,雨季' AS tags, '帐篷防水性能与雨季适用说明' AS source_summary, 90 AS score
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋能抗多少度？冬天露营够用吗？', '亲，这款是黑冰B400鹅绒睡袋，舒适温度-5度，极限能到-11度，秋冬露营完全够。充绒量400g，蓬松度700FP，压缩后只有橄榄球大小很轻便。我上个月在长白山零下8度用，里面穿个保暖内衣睡得很暖和。面料是防泼水涤纶，不小心蹭到露水也不湿。成色9新，无破损无跑绒。', '睡袋,黑冰,鹅绒,保暖,低温', '睡袋保暖性能与温标说明', 92
  UNION ALL SELECT 'sports_outdoor_gear', '登山包容量多大？背负系统舒服吗？', '亲，这款是奥斯普瑞小鹰38L登山包，空速背负系统透气性很好，夏天背也不闷。背负是网状背板，贴合背部减轻压力，我背20kg走了一天香山没觉得累。腰带有加厚海绵，髋部承重到位。有防雨罩、水袋仓、登山杖挂点。成色8.5新，用了两年走短线露营，无破损拉链顺滑。', '登山包,小鹰,背负,容量,透气', '登山包容量与背负系统说明', 89
  UNION ALL SELECT 'sports_outdoor_gear', '炉具是防风的吗？高原能用吗？', '亲，这款是火枫黄钒钛集成炉，自带挡风板防风效果很好，高原也能用。我去年在西藏海拔4500米烧水，3分钟烧开，比普通炉头快很多。火力可调节，慢炖煮面都行。配套的锅架稳定性好，放1L锅不会翻。成色9新，用了5次，气罐接口通用，野外生存利器。', '炉具,防风,高原,火枫,集成炉', '炉具防风性能与高原适用说明', 88
  UNION ALL SELECT 'sports_outdoor_gear', '登山杖是铝合金还是碳纤维？结实吗？', '亲，这款是黑钻Distance碳纤维折叠杖，外杖碳纤维内杖铝合金，兼顾轻量和强度。两根一起才360g，比纯铝合金轻一半。折叠后只有36cm放背包侧面很方便。EVA把手握感好不磨手，腕带是加宽款支撑力强。我爬华山用了一年，杖尖碳钨钢耐磨，没变形。成色9新。', '登山杖,碳纤维,黑钻,轻量,折叠', '登山杖材质与轻量化说明', 87
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷是几人帐？多重？背包能装下吗？', '亲，这款是三峰出超轻单人帐，重量只有1.1kg，包装后40乘15cm，登山包侧袋轻松装下。双层设计，内帐透气外账防水，比普通双人帐轻一半。我走长线徒步专门买的，用过3次成色9新。配地钉风绳全套，一个人露营刚好，两个人挤一点也行。超轻装备控必备，性价比很高。', '帐篷,单人,超轻,三峰出,轻量化', '帐篷容量与轻量化说明', 86
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋用久了还会蓬松吗？有没有跑绒？', '亲，这款黑冰睡袋用的是高蓬松度鹅绒，用了两年蓬松度没衰减。我每次用完都会晾干再收纳，避免压缩存放影响蓬松度。面料是防钻绒高密度涤纶，偶尔有一两根绒毛钻出是正常现象，不影响保暖。收纳袋是大一号的，不长期压缩能延长寿命。成色9新，保养得很好。', '睡袋,蓬松,跑绒,鹅绒,保养', '睡袋蓬松度与跑绒情况说明', 85
  UNION ALL SELECT 'sports_outdoor_gear', '背包防水吗？需要单独配防雨罩吗？', '亲，这款背包面料本身有防泼水涂层，毛毛雨没问题，但下大雨还是建议用防雨罩。背包自带一个防雨罩在底部拉链仓里，红色反光条夜间安全。我一般还会用防水袋装贵重物品，双重保险。面料是500D尼龙，耐磨抗撕裂，灌木丛里钻也不怕刮。成色9新，防雨罩完好。', '登山包,防水,防雨罩,尼龙,耐磨', '背包防水性能与防雨罩说明', 84
  UNION ALL SELECT 'sports_outdoor_gear', '炉具能用普通气罐吗？还是必须专用？', '亲，这款炉具是通用接口的，常见的扁气罐和长气罐都能用，高山气罐也可以。我买过火枫、脉鲜、雪诺必克的气罐都用过没问题。气罐接口是螺纹标准件，市面上99%的气罐都兼容。配套送一个转接头，可以接卡式气罐。出门在外气罐好买最重要，这个炉具很实用。', '炉具,气罐,通用,接口,兼容', '炉具气罐兼容性说明', 83
  UNION ALL SELECT 'sports_outdoor_gear', '登山杖长度能调节吗？我身高175合适吗？', '亲，这款登山杖长度可调105到125cm，您身高175完全合适。一般公式是身高乘0.68，您大概119cm，在这个范围内。杖身有刻度标记，调好刻度记住就行。下坡调长上坡调短，平路适中。腕带和把手高度也可以调。我身高180用着正好，成色9新，调节顺滑不卡顿。', '登山杖,调节,身高,刻度,腕带', '登山杖长度调节与身高适配', 82
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷搭起来复杂吗？一个人能搞定吗？', '亲，这款是交叉杆结构，两个人杆子一交叉穿进去就立起来了，一个人5分钟搞定。我第一次搭看了下说明书就会了，比想象中简单。内帐先搭再披外账，雨天也不会湿内帐。拆卸也快，3分钟收好装袋。送一套地钉风绳，风大的时候拉上很稳。成色9新，说明书齐全。', '帐篷,搭建,交叉杆,简单,说明书', '帐篷搭建难度与操作说明', 81
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋能机洗吗？怎么清洗保养？', '亲，鹅绒睡袋不建议经常洗，会影响蓬松度和保暖性。我一般用完晾一下散味就行，真要洗建议手洗，用专用羽绒清洗剂，轻柔挤压不要拧。洗完阴干不要暴晒，干后拍打让羽绒恢复蓬松。收纳时放在大收纳袋里松散存放，不要长期压缩。成色9新，我保养得很好没洗过。', '睡袋,清洗,保养,鹅绒,蓬松', '睡袋清洗保养方法说明', 80
  UNION ALL SELECT 'sports_outdoor_gear', '背包承重多少？背20kg会断吗？', '亲，这款背包设计承重25kg，背20kg完全没问题。背负系统是铝合金框架加网状背板，重量转移到髋部，肩膀压力小。腰带加厚海绵，扣紧后很贴合。我背过18kg走三天重装露营，背包一点没变形。缝线是四线加固，受力点都做了补强。成色8.5新，结实耐用。', '登山包,承重,腰带,铝合金,加固', '背包承重与受力设计说明', 86
  UNION ALL SELECT 'sports_outdoor_gear', '炉具火力大吗？烧开一壶水要多久？', '亲，这款炉具功率2800W，火力很大，烧开1L水大概3分钟，比家里煤气灶还快。我在海拔3000米烧水也就4分钟，高原沸点低更快。火力可以调节，大火烧水小火煮面，很实用。配套锅架放1.5L锅都很稳。气罐一罐能烧约1小时，户外两三天的量足够了。成色9新。', '炉具,火力,烧水,功率,调节', '炉具火力大小与烧水效率说明', 85
  UNION ALL SELECT 'sports_outdoor_gear', '登山杖下坡好用吗？会不会滑？', '亲，这款登山杖杖尖是碳钨钢材质，硬度很高，在岩石、泥土、雪地上都不滑。下坡时把杖尖插前面借力，膝盖压力小很多。我下华山十八弯全程靠它，膝盖一点都不疼。下坡建议把杖调长5到10cm，发力更顺。配橡胶杖套，在硬地面也能用不打滑。成色9新，杖尖完好。', '登山杖,下坡,碳钨钢,防滑,杖套', '登山杖下坡性能与防滑说明', 84
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷透气吗？早上起来会不会结露？', '亲，这款是双层帐，内帐是透气网纱，外账防水，两层之间有空气层，透气防结露效果很好。我夏天在湖边露营，早上外账有露水但内帐干爽。顶部有通风口可以拉开调节气流。如果是单层帐才会结露，双层帐不会有这个问题。成色9新，透气性完好，夏天用很舒服。', '帐篷,透气,结露,双层,通风', '帐篷透气性与防结露说明', 83
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋拉链顺畅吗？会不会卡布？', '亲，这款睡袋拉链是YKK防卡布设计，两侧有挡布条隔离，拉的时候不会卡到面料。我用了一年从没卡过，拉起来很顺滑。拉链是双头的，可以从底部打开通风，脚部也可以单独拉开。防夹条设计很贴心。成色9新，拉链完好如初。如果真卡了慢慢拉别硬拽就行。', '睡袋,拉链,YKK,防卡,双头', '睡袋拉链顺畅性与设计说明', 82
  UNION ALL SELECT 'sports_outdoor_gear', '背包有几个口袋？分区合理吗？', '亲，这款背包分区很合理，主仓大容量装睡袋帐篷，前仓放衣物，顶包放常用小件，侧袋放水壶，腰包放手机零食。还有睡袋仓底部拉链，方便取底层物品。水袋仓有出水孔，喝水很方便。我重装露营用了一年，分区很实用，找东西不用翻遍整个包。成色8.5新，拉链都顺滑。', '登山包,口袋,分区,主仓,水袋仓', '背包分区与口袋设计说明', 85
  UNION ALL SELECT 'sports_outdoor_gear', '炉具能带上飞机吗？气罐能过安检吗？', '亲，炉具本身可以带上飞机，我坐过去西藏的航班没问题。但是气罐不能带，无论托运还是随身都不行，气罐属于易燃压缩气体。建议到了当地户外店买气罐，西藏、四川、云南这些户外热门地都有卖。炉具拆开清洁干净放行李箱托运就行。成色9新，出门方便携带。', '炉具,飞机,安检,气罐,托运', '炉具飞机携带与安检说明', 80
  UNION ALL SELECT 'sports_outdoor_gear', '登山杖能带上飞机吗？还是必须托运？', '亲，登山杖有金属杖尖属于锐器，不能随身带上飞机，必须托运。我每次出行都把杖拆开放行李箱托运，从未被拦过。建议把杖尖用橡胶套套好，避免戳坏行李箱。折叠杖的好处就是短，放行李箱不占地方。如果您经常飞，这款折叠杖特别合适。成色9新，附赠杖尖套。', '登山杖,飞机,托运,折叠,杖尖', '登山杖飞机携带与托运说明', 79
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷地钉够用吗？要不要额外买？', '亲，这款帐篷自带8根铝合金地钉，够用了。铝合金地钉比铁地钉轻便不生锈，强度也够。如果是硬地面建议再配几根钛合金地钉更耐砸。风大的时候建议多打几个地钉加风绳，我遇到过山顶大风，多打两根地钉帐篷稳如泰山。送的收纳袋装地钉不丢。成色9新，地钉齐全。', '帐篷,地钉,铝合金,风绳,加固', '帐篷地钉配置与加固说明', 81
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋收纳袋是压缩袋吗？能压多小？', '亲，这款睡袋配两个收纳袋，一个是松散存放的网袋，一个是出行用的压缩袋。压缩袋能把睡袋压到橄榄球大小，直径约20cm，长度35cm，放背包很省空间。压缩后大概4L体积，比不压缩小三分之二。建议平时用网袋松散存放保护羽绒，出行用压缩袋。成色9新，两个袋子都在。', '睡袋,压缩袋,收纳,体积,网袋', '睡袋压缩袋与收纳说明', 83
  UNION ALL SELECT 'sports_outdoor_gear', '背包肩带厚实吗？长时间背会勒肩膀吗？', '亲，这款背包肩带是加厚海绵加网眼透气面料，宽7cm很厚实，背20kg走一天也不会勒肩膀。肩带弧度符合人体工学，胸口有胸带固定不会左右晃。我重装三天肩部没红没痛，比那种薄肩带舒服太多。腰带也很厚，髋部承重到位。成色8.5新，海绵没塌陷。', '登山包,肩带,海绵,透气,胸带', '背包肩带舒适度与设计说明', 86
  UNION ALL SELECT 'sports_outdoor_gear', '炉具有挡风板吗？野外风大好用吗？', '亲，这款炉具自带集成挡风板，四面围合防风效果很好。我在海边露营风很大，挡风板一挡火力稳定不受影响。比那种分离式挡风板方便多了，不用单独带。挡风板是不锈钢材质，耐用不怕高温。如果遇到极端大风，可以再拿背包挡一面效果更好。成色9新，挡风板完好。', '炉具,挡风板,防风,不锈钢,集成', '炉具挡风板与防风性能说明', 84
  UNION ALL SELECT 'sports_outdoor_gear', '登山杖腕带有用吗？需要系紧吗？', '亲，腕带是登山杖很重要的部分，能借力减轻手臂负担。正确用法是手腕从下往上穿入腕带，握住把手时腕带贴合手背，下坡时用手腕压腕带借力，不是用手死握把手。我下坡全程靠腕带借力，手臂不酸膝盖也轻松。腕带要调到合适松紧，太松借不到力太紧不舒服。成色9新，腕带完好。', '登山杖,腕带,借力,下坡,正确用法', '登山杖腕带使用与借力说明', 82
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷是什么牌子的？正品吗？有购买凭证吗？', '亲，这款是三峰出官方正品，淘宝旗舰店买的，有订单截图可以发您。三峰出是国内做超轻帐篷的头部品牌，质量可靠。面料是硅浸胶尼龙，比普通帐篷轻且防水。做工看缝线就很规整，假货做不到这个工艺。我买的时候899，现在500出，用了3次成色9新，性价比很高。', '帐篷,三峰出,正品,凭证,品牌', '帐篷品牌与正品验证说明', 88
  UNION ALL SELECT 'sports_outdoor_gear', '睡袋是鹅绒还是鸭绒？保暖差别大吗？', '亲，这款是鹅绒的，比鸭绒保暖性更好且异味小。鹅绒蓬松度更高，同样重量下保暖性比鸭绒强约15%。这款蓬松度700FP，充绒量400g，保暖性在同价位很出色。鸭绒睡袋便宜但有腥味，鹅绒几乎没味道。我嗅觉敏感用鹅绒完全没问题。成色9新，无异味无跑绒。', '睡袋,鹅绒,鸭绒,蓬松度,保暖', '睡袋鹅绒鸭绒区别与保暖性', 87
  UNION ALL SELECT 'sports_outdoor_gear', '背包能塞下睡袋帐篷防潮垫吗？', '亲，这款38L背包空间够大，我重装露营塞下睡袋、单人帐篷、防潮垫、换洗衣物、炉具锅具食物还有富余。底部睡袋仓放睡袋，主仓中间放帐篷，上面放衣物，前仓放食物炉具。防潮垫我外挂在背包侧面。只要合理收纳，38L走3天短线完全够用。成色8.5新，容量充足。', '登山包,容量,收纳,重装,露营', '背包容量与收纳能力说明', 85
  UNION ALL SELECT 'sports_outdoor_gear', '这套户外装备能再便宜点吗？打包收吗？', '亲，帐篷300、睡袋350、背包280、炉具120、登山杖180，单买总价1230。如果您打包一起收，给您优惠价1000包邮，相当于8折。装备都是9成新，品质很好，这套配齐基本户外露营全覆盖了。打包出对我也省心，对您也划算。诚心要的话980给您，再送几个地钉和气罐。', '户外装备,打包,优惠,套装,议价', '户外装备打包优惠与议价说明', 86
  UNION ALL SELECT 'sports_outdoor_gear', '帐篷用完需要晾干吗？收纳要注意什么？', '亲，帐篷用完一定要晾干再收纳，不然会发霉。我每次回来都把内外帐撑开放通风处晾半天，确保完全干燥再装袋。如果沾了泥巴，用湿布擦干净不要用洗涤剂，会破坏防水涂层。收纳时不要压太紧，松散放更好。地钉风绳单独装小袋，避免刮伤帐篷。成色9新，保养得当。', '帐篷,晾干,收纳,保养,防水涂层', '帐篷晾干收纳与保养说明', 83
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 3. sports_apparel - 运动服饰 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.56', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'sports_apparel' AS code, '这件速干衣是什么面料？透气吗？' AS question, '亲，这款是迪卡侬速干T恤，面料是100%聚酯纤维，吸湿排汗速干。我跑步出汗后10分钟就干了，不会黏在身上难受。面料有网眼结构透气性很好，夏天穿比棉T恤舒服太多。领口是圆领设计不勒脖子，下摆有反光条夜跑安全。原价79买的，穿了3次成色9.5新，几乎全新。' AS answer, '速干衣,聚酯纤维,透气,迪卡侬,夜跑' AS tags, '速干衣面料与透气性能说明' AS source_summary, 86 AS score
  UNION ALL SELECT 'sports_apparel', '运动裤尺码准吗？我穿M码合适吗？', '亲，这款运动裤尺码偏标准，我身高175体重70kg穿M码刚好。裤长98cm，腰围是松紧带加抽绳设计，有弹性不勒肚子。建议您按平时穿的尺码拍就行。如果您介于两个尺码之间，建议选大一码，运动时更舒服。我有实物尺码表可以发您参考。成色9新，洗过两次无起球。', '运动裤,尺码,M码,松紧带,弹性', '运动裤尺码与穿着建议说明', 84
  UNION ALL SELECT 'sports_apparel', '运动文胸是高强度还是低强度？跑步会晃吗？', '亲，这款是Shock Absorber高强度运动文胸，跑步跳绳都稳稳的不晃。包裹性很好，肩带加宽不勒肩膀，后背是工字型设计不妨碍活动。我D杯跑步完全没困扰，比低强度文胸强太多了。面料透气排汗，洗了不变形。原价280买的，穿了5次成色9新，是我买过最满意的运动文胸。', '运动文胸,高强度,跑步,包裹,防震', '运动文胸强度与防震性能说明', 90
  UNION ALL SELECT 'sports_apparel', '瑜伽服弹性好吗？做拉伸会紧吗？', '亲，这款瑜伽服是瑜伽服套装，面料是锦纶加氨纶混纺，四面弹性很好。我做各种拉伸动作完全不紧绷，下犬式、战士式都没束缚感。高腰裤包裹性很好不会卷边，上衣是运动背心款不露。面料柔软亲肤不起球，洗了5次还像新的。原价199套装，穿了半年成色9新。', '瑜伽服,弹性,锦纶,氨纶,拉伸', '瑜伽服弹性和拉伸舒适性说明', 87
  UNION ALL SELECT 'sports_apparel', '运动服起球吗？洗过几次了？', '亲，这款运动服面料是加捻涤纶，抗起球处理过的，我洗了8次完全没起球。普通廉价运动服洗两次就起球，这款品质好很多。面料质感厚实不透，做运动不会走光。拉链是YKK的，用了半年顺滑没坏。原价259买的，因为减肥成功换了小码才出，成色8.5新。', '运动服,起球,涤纶,YKK,抗起球', '运动服起球情况与洗涤次数说明', 83
  UNION ALL SELECT 'sports_apparel', '速干衣有异味吗？出汗后会臭吗？', '亲，这款速干衣有抗菌防臭处理，我跑步出汗后晾干基本没味道。聚酯纤维面料本身快干，不容易滋生细菌，比棉T恤好很多。我连续穿两天跑步也没异味。如果味道大建议用运动专用洗涤剂清洗，不要用柔顺剂会堵塞纤维影响排汗。成色9.5新，穿了3次无异味。', '速干衣,异味,抗菌,防臭,排汗', '速干衣异味与抗菌性能说明', 82
  UNION ALL SELECT 'sports_apparel', '运动裤是紧身款还是宽松款？' AS question, '亲，这款是修身款，不是紧身裤也不是阔腿裤，介于两者之间。裤型微收脚，视觉显瘦不臃肿。面料有弹性贴身但不紧绷，运动时不会晃来晃去。我健身跑步都穿它，做深蹲弓步完全不受限。如果您喜欢宽松款我也有另一款可选。成色9新，黑色百搭好看。', '运动裤,修身,弹性,健身,百搭', '运动裤版型与穿着体验说明', 84
  UNION ALL SELECT 'sports_apparel', '运动文胸尺码怎么选？我75C合适吗？', '亲，这款运动文胸尺码是按普通内衣尺码来的，您75C建议选75C码。文胸下围是松紧带，75到80都能穿。罩杯是模压固定杯，包裹性好不跑杯。肩带可以调节长度，找到合适松紧就行。如果您介于两个尺码，运动文胸建议选小一码更稳固。成色9新，洗过3次不变形。', '运动文胸,尺码,75C,下围,模压杯', '运动文胸尺码选择与建议说明', 85
  UNION ALL SELECT 'sports_apparel', '瑜伽服会透吗？深蹲会走光吗？', '亲，这款瑜伽裤是加厚不透面料的，深蹲弯腰完全不走光。我专门测试过，白色内裤穿里面深蹲都看不出。面料是高密度锦纶，比那种薄款瑜伽裤厚实但不闷热。高腰设计包裹性好不会卷边。颜色是经典黑色百搭显瘦。原价159买的，穿了半年成色9新，性价比很高。', '瑜伽服,不透,深蹲,高腰,黑色', '瑜伽服不透性与深蹲测试说明', 88
  UNION ALL SELECT 'sports_apparel', '运动服是哪个牌子的？正品吗？', '亲，这款是安德玛(Under Armour)正品，专柜买的，有购物小票可以发您。面料是UA专属HeatGear科技面料，排汗速干效果一流。领标有防伪标，吊牌齐全。UA的品质不用多说，专业运动品牌做工扎实。原价399，因为减肥换了小码才出，成色9新，性价比很高。', '运动服,安德玛,正品,小票,HeatGear', '运动服品牌与正品验证说明', 89
  UNION ALL SELECT 'sports_apparel', '速干衣能机洗吗？怎么洗不掉色？', '亲，速干衣可以机洗，建议冷水轻柔模式，跟深色衣物分开洗。不要用柔顺剂，会堵塞纤维影响排汗。不要暴晒，阴干即可，面料速干半天就干了。我洗了3次完全没掉色没变形。如果味道大可以用运动专用洗涤剂浸泡15分钟再洗。成色9.5新，洗护得当。', '速干衣,机洗,掉色,柔顺剂,洗护', '速干衣洗涤方法与掉色说明', 80
  UNION ALL SELECT 'sports_apparel', '运动裤有口袋吗？能放手机吗？', '亲，这款运动裤两侧有拉链口袋，放手机钥匙完全不会掉。我跑步时放iPhone14刚好，拉链顺滑不卡。后腰还有一个暗袋放卡片纸巾很方便。口袋面料是网眼不影响透气。拉链是YKK的耐用不坏。这条裤子跑步健身都能穿，口袋设计很实用。成色9新，拉链完好。', '运动裤,口袋,拉链,手机,YKK', '运动裤口袋设计与实用性说明', 83
  UNION ALL SELECT 'sports_apparel', '运动文胸洗涤要注意什么？机洗会变形吗？', '亲，运动文胸建议手洗，机洗容易导致模压杯变形和松紧带松弛。如果机洗请放洗衣袋，用轻柔模式冷水洗。不要甩干不要暴晒，阴干即可。我一般洗完用手整形一下罩杯，保持形状。不要用柔顺剂会影响弹性。我这件洗了5次还像新的，保养得当。成色9新。', '运动文胸,洗涤,手洗,变形,保养', '运动文胸洗涤与保养说明', 81
  UNION ALL SELECT 'sports_apparel', '瑜伽服是套装吗？上衣和裤子分开卖吗？', '亲，这款是套装的，上衣加裤子一起出，不拆卖。套装款式搭配好看，颜色统一。上衣是运动背心款，裤子是高腰九分裤，套装原价199。如果您只要上衣或裤子，建议去店里单买，我这边拆了不好出。套装出性价比高，相当于单件不到100。成色9新，穿过5次。', '瑜伽服,套装,上衣,裤子,不拆卖', '瑜伽服套装与拆卖说明', 82
  UNION ALL SELECT 'sports_apparel', '运动服有几种颜色？图片是实拍吗？', '亲，这款运动服有黑色、深蓝、灰色三个颜色，图片都是实物拍摄的，没有滤镜色差。我建议黑色，最百搭显瘦，耐脏好洗。深蓝色显气质但浅色污渍明显。灰色适合内搭，单穿容易显汗渍。所有颜色面料一样，只是染色不同。成色9新，黑色款最经典。', '运动服,颜色,实拍,黑色,百搭', '运动服颜色与实拍说明', 80
  UNION ALL SELECT 'sports_apparel', '速干衣防晒吗？户外跑步会晒黑吗？', '亲，这款速干衣有UPF50+防晒处理，能阻挡98%紫外线，户外跑步不怕晒黑。我夏天户外跑10公里，手臂完全没晒黑。面料轻薄透气，比涂防晒霜舒服多了。领口是立领设计，脖子也能保护到。袖长到手腕，手臂全覆盖。原价99买的，穿了5次成色9新。', '速干衣,防晒,UPF50,户外,紫外线', '速干衣防晒性能与户外适用', 86
  UNION ALL SELECT 'sports_apparel', '运动裤弹性会松吗？穿久了会变形吗？', '亲，这款运动裤用的是莱卡氨纶，弹性持久不易松弛。我穿了半年每周3次，弹性还像新的一样。莱卡比普通氨纶贵3倍，但弹性寿命长很多。面料是双纱线织造，不容易变形起球。腰头松紧带也是高品质，不会越穿越松。成色8.5新，弹性完好如初。', '运动裤,弹性,莱卡,变形,持久', '运动裤弹性持久性与变形说明', 85
  UNION ALL SELECT 'sports_apparel', '运动文胸后背是什么款式？好看吗？', '亲，这款后背是工字型交叉肩带设计，既好看又稳固。交叉肩带分散受力，跑步时不晃动，背部线条也好看。肩带是加宽款不勒肩膀，也不会露出来很尴尬。我穿低背运动服时露出交叉带还挺好看的。后背透气网眼设计，散热性好。成色9新，颜值和功能兼顾。', '运动文胸,后背,工字型,交叉肩带,美观', '运动文胸后背设计与美观说明', 84
  UNION ALL SELECT 'sports_apparel', '瑜伽服显瘦吗？我微胖能穿吗？', '亲，这款瑜伽裤是高腰提臀款，微胖穿也很好看。高腰收腹把小肚子收住，提臀设计让臀部更翘。九分裤露出脚踝视觉显腿长。我120斤穿M码很合适，不紧不松刚好。黑色显瘦效果最好。如果您150斤以上建议选L码。面料有弹性不勒肉，穿着舒服。成色9新。', '瑜伽服,显瘦,微胖,高腰,提臀', '瑜伽服显瘦效果与微胖适用', 86
  UNION ALL SELECT 'sports_apparel', '运动服拉链是金属的还是塑料的？耐用吗？', '亲，这款运动服拉链是YKK金属拉链，比塑料拉链耐用很多。金属拉链顺滑不卡，用了半年跟新的一样。塑料拉链容易断齿，金属拉链寿命长很多。拉链头有绳圈方便拉动，戴手套也能拉。拉链内侧有挡风条，拉起来不会夹到下巴。成色9新，拉链完好。', '运动服,拉链,金属,YKK,耐用', '运动服拉链材质与耐用性说明', 82
  UNION ALL SELECT 'sports_apparel', '速干衣领口会变形吗？洗后会松吗？', '亲，这款速干衣领口是加厚罗纹领，洗了不容易变形。我洗了3次领口还跟新的一样，没有变松或波浪边。廉价速干衣洗一次领口就变形，这款品质好很多。领口有定型条支撑，保持形状。建议洗的时候不要拉扯领口，晾干时整形一下。成色9.5新，领口完好。', '速干衣,领口,变形,罗纹,定型', '速干衣领口变形与定型说明', 81
  UNION ALL SELECT 'sports_apparel', '运动裤是长裤还是短裤？裤长多少？', '亲，这款是九分裤，裤长90cm，我身高175刚好到脚踝上方。九分裤露出脚踝显腿长，运动时不拖地也方便。如果您身高160到170穿刚好，160以下可能有点长。我也有同款长裤和短裤可选。九分裤最百搭，跑步健身日常都能穿。成色9新，裤长合适。', '运动裤,九分裤,裤长,身高,百搭', '运动裤裤长与身高适配说明', 83
  UNION ALL SELECT 'sports_apparel', '运动文胸透气吗？夏天穿会闷吗？', '亲，这款运动文胸面料是网眼透气设计，前胸和后背都有透气孔，夏天穿不闷。我夏天户外跑10公里，文胸里没积汗很干爽。面料是排汗速干材质，出汗后5分钟就干了。模压杯也有透气孔，不会闷热。比那种厚海绵文胸透气多了。成色9新，夏天跑步首选。', '运动文胸,透气,网眼,夏天,排汗', '运动文胸透气性与夏季适用', 85
  UNION ALL SELECT 'sports_apparel', '瑜伽服是哪个牌子？有吊牌吗？', '亲，这款是MAIA ACTIVE玛娅的瑜伽服套装，专柜买的吊牌还在。MAIA是国产高端瑜伽服品牌，面料和设计都很出色，对标Lululemon。吊牌价上衣199加裤子229共428，我200出，相当于4.7折。面料是专业运动面料，排汗弹力都很好。成色9新，穿了5次，因为身材变化才出。', '瑜伽服,MAIA,吊牌,品牌,专业', '瑜伽服品牌与吊牌说明', 88
  UNION ALL SELECT 'sports_apparel', '运动服尺码偏大还是偏小？我175 75kg穿什么码？', '亲，这款运动服尺码偏标准，您175 75kg建议穿L码。我身高175 70kg穿M码刚好，您比我重5kg L码会更舒服。运动服建议选合身不要太紧，方便活动。如果您喜欢宽松感可以选XL码。我有实物尺码表可以发您参考，胸围腰围肩围都有标注。成色9新，L码黑色。', '运动服,尺码,L码,身高体重,标准', '运动服尺码选择与建议说明', 84
  UNION ALL SELECT 'sports_apparel', '速干衣能冬天穿吗？还是只能夏天穿？', '亲，这款速干衣是薄款，适合春夏秋三季。冬天可以作为打底穿在保暖衣里面，排汗效果很好。我冬天滑雪就穿它打底，出汗后不黏身很舒服。单穿的话适合10度以上天气，低于10度建议穿长袖加绒款。我也有加绒速干衣可选，冬天户外跑更暖和。成色9.5新，薄款百搭。', '速干衣,冬天,打底,薄款,三季', '速干衣季节适用与冬季打底', 82
  UNION ALL SELECT 'sports_apparel', '运动裤腰头会卷边吗？深蹲会往下滑吗？', '亲，这款运动裤腰头是加宽高腰设计，配防滑硅胶条，深蹲不会卷边也不会往下滑。我做深蹲100kg完全没困扰，裤子贴合稳固。腰头松紧带加抽绳双保险，怎么动都不掉。比那种窄腰头的好太多。面料弹力够大，深蹲到底不紧绷。成色9新，腰头完好如初。', '运动裤,腰头,卷边,深蹲,防滑', '运动裤腰头与深蹲稳定性说明', 86
  UNION ALL SELECT 'sports_apparel', '运动文胸能日常穿吗？还是只能运动穿？', '亲，这款运动文胸设计比较时尚，日常穿也完全可以。我自己平时出门就经常穿，配个外套或开衫很百搭。模压杯有支撑力，日常穿不用再穿普通文胸，一举两得。肩带是可调节的，配不同领口衣服都好看。不过如果您是通勤正式场合，建议还是穿普通文胸。成色9新。', '运动文胸,日常,穿搭,模压杯,百搭', '运动文胸日常穿着与搭配说明', 83
  UNION ALL SELECT 'sports_apparel', '这套运动服能便宜点吗？诚心收的。', '亲，这套运动服原价399，我180出已经很实在了，相当于4.5折。安德玛正品，9成新，穿了几次因为减肥换码才出。如果您诚心要，160包邮给您，这是底价了。运动服品质好穿几年都不变形，比买便宜货划算。如需配套运动裤可以一并出，再优惠10元。', '运动服,议价,安德玛,优惠,包邮', '运动服议价与优惠说明', 84
  UNION ALL SELECT 'sports_apparel', '速干衣有反光条吗？夜跑安全吗？', '亲，这款速干衣下摆和后背都有3M反光条，夜跑时车灯一照很亮，安全有保障。我经常晚上7点后跑步，反光条让司机很远就能看到。领口和袖口也有反光logo。反光条是热压工艺不会掉，洗了也不脱落。夜跑安全很重要，这件衣服设计很贴心。成色9.5新，反光条完好。', '速干衣,反光条,夜跑,安全,3M', '速干衣反光条与夜跑安全说明', 85
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 4. sports_cycling - 骑行装备 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.56', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'sports_cycling' AS code, '这辆自行车是什么车型？多少速的？' AS question, '亲，这辆是捷安特ATX 660山地车，21速（3乘7），Shimano Tourney变速套件。车架是铝合金材质，重量约14kg，轻便结实。轮组是26寸双层铝合金圈，耐磨抗冲击。前叉有避震功能，下坡和不平路面骑起来很稳。买了两年骑行约800公里，成色8.5新，无摔车无大修。' AS answer, '自行车,捷安特,山地车,21速,铝合金' AS tags, '自行车车型与变速配置说明' AS source_summary, 90 AS score
  UNION ALL SELECT 'sports_cycling', '电动车续航多少公里？电池还能跑多久？', '亲，这辆小牛电动车是N1S标准版，电池是博世锂电池48V 20Ah。新电池续航60公里，现在用了2年循环约200次，续航还有45公里左右。电池健康度约75%，再骑1到2年没问题。充电4到6小时充满，有BMS电池管理系统安全可靠。我每天通勤8公里，一周充一次电够用。成色8.5新，电池保养好。', '电动车,小牛,续航,电池,锂电池', '电动车续航与电池健康说明', 88
  UNION ALL SELECT 'sports_cycling', '头盔是什么牌子？有安全认证吗？', '亲，这款是GiroRegister公路头盔，通过美国CPSC和欧洲CE双重安全认证。外壳是PC一体成型，内衬是EPS发泡，抗冲击性很好。通风口有22个散热性不错，夏天骑不闷。MIPS防旋转系统能减少斜向冲击对大脑的伤害。我骑行1年没摔过，头盔无磕碰无裂纹。成色9新，安全有保障。', '头盔,Giro,认证,MIPS,安全', '头盔品牌与安全认证说明', 92
  UNION ALL SELECT 'sports_cycling', '骑行服是连体还是分体？尺码怎么选？', '亲，这款是分体骑行服，上衣加背带裤。分体比方体方便穿脱，上厕所不用脱上衣。面料是意大利MITI面料，排汗速干弹力好。上衣是修身款减少风阻，背带裤垫裆是意大利EIT坐垫，长途骑行不硌屁股。我身高175 70kg穿M码刚好，建议按平时尺码选。成色9新，穿过5次。', '骑行服,分体,背带裤,坐垫,MITI', '骑行服款式与尺码选择说明', 87
  UNION ALL SELECT 'sports_cycling', '车灯亮度多少？晚上骑够亮吗？', '亲，这款车灯是迈极炫CBL1600，亮度1600流明，晚上骑车完全够亮。有5个亮度档位可调，最高档能照200米远。电池是6700mAh，最高档续航1.5小时，最低档6小时。Type-C充电很方便，有电量显示。防水等级IPX6，下雨也能用。我夜骑1年很满意，成色9新，包装齐全。', '车灯,迈极炫,亮度,夜骑,防水', '车灯亮度与夜骑适用说明', 89
  UNION ALL SELECT 'sports_cycling', '车锁是U型锁还是链条锁？防盗够吗？', '亲，这款是克家Kryptonite Evolution U型锁，13mm硬化钢锁梁，抗液压剪抗撬。我用了2年没被撬过，停在地铁口也很安全。U型锁比链条锁轻便且防盗等级更高，搭配钢丝绳锁轮子更稳。送3把钥匙，丢了可以配。锁芯是Disc-style防撬设计。成色8.5新，锁芯顺滑。', '车锁,U型锁,克家,防盗,硬化钢', '车锁类型与防盗性能说明', 86
  UNION ALL SELECT 'sports_cycling', '自行车车架多大？我身高180能骑吗？', '亲，这辆车车架是17寸（M码），适合身高165到180cm。您180cm刚好在上限，骑起来不会觉得小。如果180以上建议选19寸（L码）车架更合适。26寸轮组通用性好，轮胎好换。座管可以调高，最大高度约90cm。我身高178骑刚好，成色8.5新，车架无变形无裂纹。', '自行车,车架,17寸,身高,轮组', '自行车车架尺寸与身高适配', 84
  UNION ALL SELECT 'sports_cycling', '电动车能上牌吗？有发票吗？', '亲，这辆小牛电动车有正规购车发票和合格证，可以上牌。我已经上了上海电动自行车牌照，过户给您只需去车管所办个手续，10分钟搞定。符合新国标，最大速度25km/h，有脚踏功能，全国都能上牌。如果您在外地，发票合格证齐全当地也能上牌。成色8.5新，手续齐全。', '电动车,上牌,发票,新国标,合格证', '电动车上牌与手续说明', 88
  UNION ALL SELECT 'sports_cycling', '头盔通风好吗？夏天戴会闷热吗？', '亲，这款Giro头盔有22个通风口，空气流通很好，夏天戴不闷热。我夏天骑行30公里，头部完全没积汗。通风口设计符合空气动力学，骑行时风从前往后流过散热。内衬是抗菌速干面料，出汗不臭可拆卸清洗。比那种便宜全包头盔透气多了。成色9新，内衬完好。', '头盔,通风,透气,夏天,内衬', '头盔通风性与夏季舒适说明', 85
  UNION ALL SELECT 'sports_cycling', '骑行服垫裆厚吗？长途骑行屁股疼吗？', '亲，这款骑行裤垫裆是意大利EIT三密度坐垫，厚薄分区设计。坐骨位置加厚减震，会阴位置薄款透气，长途骑行不硌不疼。我骑过200公里一天的长途，屁股完全不疼。垫裆有抗菌处理，不容易滋生细菌。面料贴身不摩擦，减少大腿内侧磨伤。成色9新，垫裆完好。', '骑行服,垫裆,坐垫,长途,减震', '骑行服垫裆与长途舒适性说明', 88
  UNION ALL SELECT 'sports_cycling', '车灯能充电吗？还是装电池的？', '亲，这款车灯是可充电款，内置锂电池，Type-C接口充电很方便。充满电最高档用1.5小时，最低档6小时。有4格电量显示，随时知道剩余电量。比装电池的环保省钱，不用老买电池。我用了1年电池没衰减，续航还跟新的一样。充电时红灯亮，充满绿灯亮。成色9新，包装齐全。', '车灯,充电,Type-C,电池,电量显示', '车灯充电方式与续航说明', 84
  UNION ALL SELECT 'sports_cycling', '自行车变速顺畅吗？换挡卡顿吗？', '亲，这辆捷安特变速很顺畅，Shimano Tourney套件换挡精准不卡顿。我每周保养一次，变速线定期上油，指拨顺滑。21速齿比范围大，爬坡下坡都有合适档位。前拨后拨都调校到位，链条不会掉。如果您觉得变速不够顺滑，我可以帮您调一下再发。成色8.5新，变速完好。', '自行车,变速,Shimano,换挡,保养', '自行车变速性能与保养说明', 86
  UNION ALL SELECT 'sports_cycling', '电动车电机多少瓦？爬坡够力吗？', '亲，这辆小牛电机是博世350W后置电机，扭矩40N.m，爬坡完全够力。我住的小区有地下车库坡度15度，载重75kg轻松上去。最大速度25km/h符合新国标。电机是博世品牌，耐用静音，用了2年没出过问题。起步平顺不突兀，骑行体验很好。成色8.5新，电机状态好。', '电动车,电机,博世,爬坡,功率', '电动车电机功率与爬坡能力', 87
  UNION ALL SELECT 'sports_cycling', '头盔能调节大小吗？我头围58合适吗？', '亲，这款Giro头盔有Roc Loc调节系统，头围54到61cm都能调，您58cm完全合适。后脑有旋钮调节松紧，单手就能操作。头盔内衬有不同厚度垫片可以替换，微调贴合度。建议您试戴时把调节带也调好，下巴带留一指宽最合适。成色9新，调节系统完好。', '头盔,调节,头围,Roc Loc,尺寸', '头盔调节与头围适配说明', 83
  UNION ALL SELECT 'sports_cycling', '骑行服面料透气吗？出汗会黏吗？', '亲，这款骑行服面料是意大利MITI，排汗速干透气性很好。我骑行出汗后5分钟就干了，不会黏在身上。面料有网眼结构帮助散热，腋下和后背都有透气孔。面料轻量有弹性，贴身不紧绷减少风阻。比穿棉T恤骑行舒服太多。成色9新，洗过5次面料还像新的。', '骑行服,面料,透气,排汗,MITI', '骑行服面料与透气性能说明', 86
  UNION ALL SELECT 'sports_cycling', '车灯防水吗？下雨能用吗？', '亲，这款车灯防水等级IPX6，下大雨也能正常使用。我骑行遇到暴雨车灯没进水没故障。电路有密封处理，电池仓有防水胶圈。如果您经常雨骑，建议用完擦干水分再收纳，延长寿命。我用了1年遇到3次大雨完全没问题。成色9新，防水性能可靠。', '车灯,防水,IPX6,雨骑,密封', '车灯防水性能与雨骑适用', 85
  UNION ALL SELECT 'sports_cycling', '自行车轮胎磨损严重吗？需要换吗？', '亲，这辆车轮胎是建大26乘1.95齿胎，用了800公里磨损约50%，还能再骑500公里左右。轮胎花纹清晰没磨平，抓地力没问题。没有补胎痕迹，胎壁无裂纹。如果您经常骑行，建议备一条新胎以防万一。我可以送您一个补胎工具包。成色8.5新，轮胎状态良好。', '自行车,轮胎,磨损,建大,齿胎', '自行车轮胎磨损与更换说明', 82
  UNION ALL SELECT 'sports_cycling', '电动车能折叠吗？方便带上地铁吗？', '亲，这辆小牛N1S不能折叠，是固定车架。如果您需要折叠带上地铁，我有另一款可折叠电动车可选。不过这辆车轻便（约35kg），有提手可以搬动。如果是短距离搬动没问题，上楼放电梯也可以。折叠车虽然方便但续航和动力不如这款。成色8.5新，根据您的需求选。', '电动车,折叠,地铁,轻便,车架', '电动车折叠与便携性说明', 80
  UNION ALL SELECT 'sports_cycling', '头盔有多重？戴久了会累吗？', '亲，这款Giro头盔重量只有250g，非常轻便，戴一天都不会累。我骑行5小时完全没感觉头上有重量。轻量化设计是Giro的强项，比那些400g以上的头盔舒服太多。头盔重量分布均匀，不会前后失衡。内衬贴合头部不晃动。成色9新，轻便是最大优点。', '头盔,重量,轻便,佩戴,舒适', '头盔重量与佩戴舒适说明', 84
  UNION ALL SELECT 'sports_cycling', '骑行服有反光条吗？夜骑安全吗？', '亲，这款骑行服后背和腿部都有3M反光条，夜骑时车灯一照很亮很安全。我经常夜骑20公里，反光条让司机很远就能看到。反光条是热压工艺不会脱落，洗了也不掉。颜色是亮黄色高 visibility，白天也很显眼。夜骑安全第一，这件骑行服设计很贴心。成色9新，反光条完好。', '骑行服,反光条,夜骑,安全,亮色', '骑行服反光条与夜骑安全说明', 85
  UNION ALL SELECT 'sports_cycling', '车灯安装方便吗？需要工具吗？', '亲，这款车灯安装很简单，不用工具。配的支架用橡胶圈固定在车把上，3秒拆装。我经常停车时把车灯拆下来带走，防止被偷。支架兼容所有车把直径（22到35mm），山地车公路车都能装。灯体可以快拆，充电也方便。成色9新，支架和灯体都在。', '车灯,安装,支架,快拆,橡胶圈', '车灯安装方式与便捷性说明', 82
  UNION ALL SELECT 'sports_cycling', '车锁钥匙能配吗？丢了一把怎么办？', '亲，这款克家U型锁送3把钥匙，丢了可以找锁匠配，或者联系克家售后补寄。钥匙是十字锁芯防盗性高，不容易被复制。建议您把备用钥匙放家里和办公室各一把，以防万一。我用了2年没丢过钥匙。锁有终身质保，非人为损坏可以换新。成色8.5新，3把钥匙齐全。', '车锁,钥匙,配钥匙,质保,十字锁', '车锁钥匙与售后说明', 81
  UNION ALL SELECT 'sports_cycling', '自行车刹车是什么类型？制动力够吗？', '亲，这辆捷安特用的是Shimano油压碟刹，制动力比V刹强30%，下坡急停很稳。我下坡速度30km/h急停，2米内停住不打滑。油压碟刹手感轻盈，一指就能刹住不费力。刹车片是树脂款，耐磨不响。前刹后刹都很灵敏，雨天制动也不衰减。成色8.5新，刹车状态良好。', '自行车,刹车,碟刹,油压,Shimano', '自行车刹车类型与制动性能', 88
  UNION ALL SELECT 'sports_cycling', '电动车有防盗功能吗？被偷会报警吗？', '亲，这辆小牛有GPS定位和电子围栏功能，被偷可以通过APP实时定位。如果车辆被移动会推送报警通知。电机锁开启后推不动车，必须有钥匙才能骑。电池也有锁，防止被拆走偷电池。我用了2年没被偷过，停在户外也放心。APP功能齐全，成色8.5新，防盗可靠。', '电动车,防盗,GPS,报警,电池锁', '电动车防盗功能与安全说明', 87
  UNION ALL SELECT 'sports_cycling', '头盔内衬能拆洗吗？出汗会有味道吗？', '亲，这款Giro头盔内衬是可拆卸的，魔术贴粘贴拆装方便。我每个月拆下来手洗一次，用中性洗涤剂阴干。内衬是抗菌速干面料，出汗不容易有味道。用了1年完全没有异味。建议经常洗内衬，头盔戴久了汗渍和油脂会滋生细菌。成色9新，内衬完好可拆洗。', '头盔,内衬,拆洗,抗菌,异味', '头盔内衬拆洗与异味说明', 83
  UNION ALL SELECT 'sports_cycling', '骑行服是哪个牌子？正品吗？有吊牌吗？', '亲，这款是捷酷(JAKROO)骑行服套装，国产专业骑行品牌，淘宝旗舰店买的。面料是意大利MITI，做工和设计都很专业。吊牌还在，上衣299加裤子399共698，我300出相当于4.3折。面料排汗弹力都很好，跟Lululemon品质差不多。成色9新，穿过5次无起球无变形。', '骑行服,捷酷,正品,吊牌,MITI', '骑行服品牌与正品验证说明', 86
  UNION ALL SELECT 'sports_cycling', '自行车能改装吗？我想换碟刹和变速。', '亲，这辆捷安特车架支持改装，但我建议您原车配置就够用了。如果真要改，碟刹和变速套件改装费用大概800到1500，不如直接买辆高配车。原车Shimano Tourney 21速日常骑行完全够，油压碟刹制动力也够。如果您是进阶玩家想升级，我可以推荐改装方案。成色8.5新。', '自行车,改装,碟刹,变速,升级', '自行车改装与升级建议说明', 84
  UNION ALL SELECT 'sports_cycling', '这辆车能再便宜点吗？诚心要的。', '亲，这辆捷安特ATX 660原价1898，我800出已经很实在了，相当于4.2折。用了2年成色8.5新，无摔车无大修。如果您诚心要，750包邮给您，这是底价了。捷安特山地车保值率高，骑3年还能卖500。如需配套头盔锁可以一并出，再优惠50元。', '自行车,议价,捷安特,优惠,包邮', '自行车议价与优惠说明', 85
  UNION ALL SELECT 'sports_cycling', '电动车电池能取下来充电吗？' AS question, '亲，这辆小牛电池是可拆卸的，在座椅下方，用钥匙打开就能取出来。我住6楼没电梯，都是把电池拎上楼充电，很方便。电池重约8kg，女士也能拎动。充电器是原装的，4到6小时充满，有指示灯显示。电池有提手设计方便携带。成色8.5新，电池和充电器齐全。', '电动车,电池,拆卸,充电,拎楼', '电动车电池拆卸与充电说明', 86
  UNION ALL SELECT 'sports_cycling', '头盔是什么颜色？有几种颜色可选？', '亲，这款Giro头盔是亮白色，另外还有黑色、亮红色、亮蓝色可选。我手上这款是亮白色，最显眼安全，白天黑夜都容易看到。亮色头盔比暗色头盔事故率低40%，建议选亮色。如果您想要其他颜色，我可以帮您问问有没有货。成色9新，亮白色最推荐。', '头盔,颜色,亮色,安全,显眼', '头盔颜色选择与安全说明', 82
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 5. sports_fishing - 垂钓用品 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.56', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'sports_fishing' AS code, '鱼竿是什么材质？碳素还是玻璃钢？' AS question, '亲，这款是达瓦碳素台钓竿，高碳纤维材质，重量只有98g非常轻便。碳素竿比玻璃钢竿轻40%，强度却高30%，手感更灵敏。竿身是24T交叉卷布工艺，腰力强劲回鱼快。竿稍实心，防断丝设计。我用了1年钓鱼约30次，竿身无裂纹无变形。原价480，现在200出，成色9新。' AS answer, '鱼竿,碳素,达瓦,轻便,台钓' AS tags, '鱼竿材质与轻量化说明' AS source_summary, 90 AS score
  UNION ALL SELECT 'sports_fishing', '鱼线是几号的？拉力值多大？', '亲，这款是日本东丽鱼线，线径0.235mm，拉力值6.5lb，适合3到5斤的鱼。线是1.5号尼龙线，耐磨抗卷曲，入水后切水快。透明色在水里看不见，不惊鱼。我用了半年没断过线，比国产线强太多。线是100m一盘，我用了一半还剩50m左右。成色9新，原价45一盘。', '鱼线,东丽,拉力,尼龙,1.5号' AS tags, '鱼线规格与拉力性能说明' AS source_summary, 86
  UNION ALL SELECT 'sports_fishing', '鱼饵是商品饵还是自制饵？什么味型？', '亲，这款是老坛玉米饵，是商品窝料，发酵玉米粒味型，鲫鱼鲤鱼草鱼都爱吃。我上个月去水库打窝，3小时上了8条鲫鱼2条鲤鱼，效果很好。饵料是真空包装保质期1年，未开封可以放很久。开袋后建议3天内用完，否则会变干。我囤了5包用不完出2包，每包500g。成色全新未拆封。', '鱼饵,老坛玉米,商品饵,窝料,味型' AS tags, '鱼饵类型与味型效果说明' AS source_summary, 84
  UNION ALL SELECT 'sports_fishing', '鱼钩是几号的？什么钩型？' AS question, '亲，这款是伊势尼5号鱼钩，无倒刺设计，适合钓2到5斤的鲫鱼鲤鱼。钩尖锋利刺鱼快，钩条粗强度高不容易拉直。无倒刺对鱼伤害小，放流友好，取钩也方便。我用了半年钓了50多条鱼，钩尖还锋利没磨钝。一盒50枚，用了20枚还剩30枚。成色9新，原价15一盒。', '鱼钩,伊势尼,5号,无倒刺,锋利' AS tags, '鱼钩型号与钩型说明' AS source_summary, 83
  UNION ALL SELECT 'sports_fishing', '渔轮是什么型号？轴承多少个？', '亲，这款是禧玛诺Spire 2000型纺车轮，5个不锈钢轴承加1个滚珠轴承，摇起来顺滑无卡顿。速比5.2:1，收线速度适中，适合路亚和台钓。卸力旋钮在前面，调节方便，最大卸力4kg。线杯容量2000型可缠0.8号PE线150米。我用了1年没出过问题，成色9新，原价380。', '渔轮,禧玛诺,纺车轮,轴承,卸力' AS tags, '渔轮型号与配置说明' AS source_summary, 89
  UNION ALL SELECT 'sports_fishing', '钓箱容量多大？能装多少东西？', '亲，这款是连球25L钓箱，内部尺寸40乘25乘25cm，能装鱼护、饵料、小配件、午餐等全套钓具。外部有4个配件盒支架，可以挂浮漂盒、子线盒、剪刀等。座椅盖承重150kg，坐一天不累。箱体是EPP材质，轻便保温，夏天鱼放里面不会死。我用了1年成色8.5新，原价220。', '钓箱,连球,容量,EPP,保温' AS tags, '钓箱容量与功能说明' AS source_summary, 87
  UNION ALL SELECT 'sports_fishing', '鱼竿长度多少？是几节的？' AS question, '亲，这款是3.6米台钓竿，4节收缩设计，收缩后长度1.05米方便携带。3.6米适合小河、池塘、黑坑钓鲫鱼，竿稍灵敏中鱼信号明显。如果是大水库建议用4.5或5.4米。竿身配有竿袋，拆卸后装袋放后备箱不占地方。我用了1年钓鱼30次，竿节接口紧密不松动。成色9新。', '鱼竿,3.6米,4节,收缩,台钓' AS tags, '鱼竿长度与节数说明' AS source_summary, 85
  UNION ALL SELECT 'sports_fishing', '鱼线会吸水吗？用久了会老化吗？', '亲，这款东丽鱼线是防水涂层处理，不吸水切水快，入水后信号传导灵敏。尼龙线正常使用寿命1年，建议每季换一次主线保证强度。我这条用了半年，强度还在90%以上。如果发现线卷曲、变色、变硬就是老化了，建议更换。避光保存能延长寿命，不要放在暴晒的车里。成色9新。', '鱼线,吸水,老化,防水,寿命' AS tags, '鱼线吸水与老化说明' AS source_summary, 82
  UNION ALL SELECT 'sports_fishing', '鱼饵开封后能放多久？怎么保存？', '亲，这款老坛玉米饵开封后建议3天内用完，否则会变干失效。如果用不完可以密封放冰箱冷藏，能保存1个月。长期不用可以冷冻保存，3个月内用完。不要暴晒不要放高温处，会变质发酸。使用时取适量，剩下的立刻密封。我囤了5包都放阴凉处，成色全新保质期内。', '鱼饵,开封,保存,冷藏,保质期' AS tags, '鱼饵开封保存与保质期说明' AS source_summary, 80
  UNION ALL SELECT 'sports_fishing', '鱼钩锋利吗？需不需要自己磨？', '亲，这款伊势尼鱼钩出厂就磨好了，钩尖非常锋利，不需要再磨。我用了半年钓了50多条鱼，钩尖还锋利没磨钝。如果钓到大鱼或者挂底，建议检查钩尖，钝了可以用磨钩石轻磨几下。新钩千万不要自己磨，反而会破坏出厂锋利度。一盒50枚，用钝了换新就行，很便宜。成色9新。', '鱼钩,锋利,磨钩,伊势尼,更换' AS tags, '鱼钩锋利度与维护说明' AS source_summary, 81
  UNION ALL SELECT 'sports_fishing', '渔轮摇起来顺滑吗？有没有异响？', '亲，这款禧玛诺渔轮摇起来非常顺滑，6个轴承转动无卡顿无杂音。我用了1年每周保养一次，内部齿轮状态良好。摇柄是加长款，省力收线快。正反转切换顺滑，不会误触。卸力系统工作稳定，大鱼冲刺时自动出线不切线。成色9新，保养得当，再战几年没问题。', '渔轮,顺滑,异响,轴承,保养' AS tags, '渔轮顺滑性与异响说明' AS source_summary, 86
  UNION ALL SELECT 'sports_fishing', '钓箱能当座椅吗？承重多少？', '亲，这款连球钓箱盖子是加厚EPP材质，承重150kg没问题，当座椅坐一天不累。盖子有防滑纹路，下雨也不滑。我自己90kg坐了一年完全没问题。箱盖是快拆设计，打开取东西方便。两侧有背带扣，可以背在身上。成色8.5新，盖子完好无裂纹。', '钓箱,座椅,承重,EPP,防滑' AS tags, '钓箱座椅功能与承重说明' AS source_summary, 84
  UNION ALL SELECT 'sports_fishing', '鱼竿是哪个牌子？正品吗？有保修吗？', '亲，这款是达瓦官方正品，淘宝旗舰店买的，有订单截图可以发您。达瓦是日本知名钓具品牌，品质有保障。竿身有防伪码，可以扫码验证。旗舰店保修1年，非人为损坏免费维修。我用了1年没出过问题，竿身无裂纹无断节。原价480，现在200出，成色9新。', '鱼竿,达瓦,正品,保修,防伪' AS tags, '鱼竿品牌与正品保修说明' AS source_summary, 88
  UNION ALL SELECT 'sports_fishing', '鱼线是浮水还是沉水？切水快吗？', '亲，这款东丽尼龙线是半浮水设计，切水速度快。入水后约3秒沉到设定深度，信号传导灵敏。比全浮水线稳定，比全沉水线容易操作。适合台钓和底钓，浮漂信号清晰。线径0.235mm，在水里几乎看不见，不惊鱼。我用了半年切水性没衰减。成色9新。', '鱼线,浮水,切水,尼龙,信号' AS tags, '鱼线浮水性与切水说明' AS source_summary, 83
  UNION ALL SELECT 'sports_fishing', '鱼饵能钓什么鱼？效果好使吗？', '亲，这款老坛玉米饵鲫鱼、鲤鱼、草鱼、鳊鱼都爱吃，效果很好。我上个月去水库打窝3小时上了8条鲫鱼2条鲤鱼，总重12斤。发酵玉米味型诱鱼力强，雾化适中不散。打窝后20分钟就能聚鱼，比自制饵料效果好。建议搭配商品饵搓饵钓，效果更佳。成色全新未拆封。', '鱼饵,鱼种,效果,鲫鱼,鲤鱼' AS tags, '鱼饵鱼种适用与效果说明' AS source_summary, 85
  UNION ALL SELECT 'sports_fishing', '鱼钩会生锈吗？海水能用吗？', '亲，这款伊势尼鱼钩是高碳钢镀镍处理，防锈性能好，淡水使用不生锈。但海水腐蚀性强，用完必须用清水冲洗晾干，否则会生锈。如果经常海钓，建议买不锈钢钩或者钛合金钩。我这款主要是淡水钓用，1年没生锈。海水用的话每次用完清洗就行。成色9新。', '鱼钩,生锈,海水,镀镍,防锈' AS tags, '鱼钩生锈与海水适用说明' AS source_summary, 82
  UNION ALL SELECT 'sports_fishing', '渔轮线杯容量多大？能缠多少米线？', '亲，这款禧玛诺Spire 2000型线杯容量是：0.8号PE线缠150米，1号PE线缠120米，1.5号尼龙线缠100米。我缠的是1号PE线120米，还有100米备用线在底。缠线要紧实均匀，不能太满否则抛投会炸线。建议缠到线杯沿下方2mm处。我缠线技术不错，缠得很整齐。成色9新。', '渔轮,线杯,容量,缠线,PE线' AS tags, '渔轮线杯容量与缠线说明' AS source_summary, 84
  UNION ALL SELECT 'sports_fishing', '钓箱保温效果好吗？夏天鱼放里面会死吗？', '亲，这款连球钓箱是EPP保温材质，保温效果6到8小时。夏天钓鱼放进去加个冰袋，鱼能活一整天不死。我有次夏天钓鱼8小时，箱内温度比外面低8度，鱼全活着带回家。冬天保温也很好，饵料不会冻硬。箱盖密封性好，不会漏水。成色8.5新，保温性能完好。', '钓箱,保温,夏天,活鱼,EPP' AS tags, '钓箱保温效果与活鱼说明' AS source_summary, 86
  UNION ALL SELECT 'sports_fishing', '鱼竿用久了会断吗？怎么保养？', '亲，碳素竿正常使用不会断，我用了1年钓过10斤的大鲤鱼没断。保养要注意：用完擦干水分，不要沙子进接口；拆卸时旋转拔出不要硬拽；不要超过竿的承受力遛鱼；存放时放竿袋避免暴晒。接口处定期抹少许护竿油保持润滑。我保养得很好，竿节紧密不松动。成色9新。', '鱼竿,保养,断裂,接口,碳素' AS tags, '鱼竿保养与防断说明' AS source_summary, 85
  UNION ALL SELECT 'sports_fishing', '鱼线缠在轮上会炸线吗？怎么处理？', '亲，尼龙线比PE线不容易炸线，这款东丽线柔韧性好，抛投顺畅。如果炸线了不要硬拉，先松开卸力，慢慢理顺。预防炸线的方法：缠线不要太满，留2mm空间；抛投力度适中；第一次抛投前先把线湿润。我用了半年只炸过1次线，是自己用力过猛。成色9新。', '鱼线,炸线,尼龙,抛投,处理' AS tags, '鱼线炸线原因与处理说明' AS source_summary, 81
  UNION ALL SELECT 'sports_fishing', '鱼饵有添加剂吗？对身体有害吗？', '亲，这款老坛玉米饵是发酵玉米加天然诱食剂，没有化学添加剂，对人体无害。但毕竟是饵料，接触后建议洗手再吃东西。味道是发酵酸甜味，不刺鼻不刺激。我用了1年没有任何不适。如果皮肤敏感，可以戴手套操作。饵料有QS食品安全认证，可以放心使用。成色全新。', '鱼饵,添加剂,安全,天然,无害' AS tags, '鱼饵添加与安全性说明' AS source_summary, 80
  UNION ALL SELECT 'sports_fishing', '鱼钩倒刺好还是无倒刺好？' AS question, '亲，看您钓什么鱼。无倒刺钩适合钓鲫鱼等小鱼，取钩快不伤鱼，适合竞技钓和放流。倒刺钩适合钓大鱼，中鱼后不容易脱钩，但取钩慢伤鱼。我这款是无倒刺5号，适合2到5斤的鲫鱼鲤鱼。如果您专钓大鱼建议买倒刺钩。无倒刺钩对鱼伤害小，放流友好。成色9新。', '鱼钩,倒刺,无倒刺,鱼种,放流' AS tags, '鱼钩倒刺选择与适用说明' AS source_summary, 82
  UNION ALL SELECT 'sports_fishing', '渔轮有异响怎么办？能自己修吗？', '亲，渔轮异响一般是齿轮缺油或者进沙子了。简单处理：打开侧盖，用棉签清理沙子，滴几滴渔轮专用润滑油。如果还响可能是齿轮磨损，建议找专业维修。我这款禧玛诺用了1年没异响，每周保养一次，内部很干净。不建议自己拆主齿轮，容易装不回去。成色9新，状态良好。', '渔轮,异响,维修,保养,润滑' AS tags, '渔轮异响处理与维修说明' AS source_summary, 81
  UNION ALL SELECT 'sports_fishing', '钓箱能放鱼护吗？容量够吗？', '亲，这款连球25L钓箱能放3米鱼护、饵料盒、小配件盒、午餐盒等全套装备。我钓鱼时鱼护放外面，箱内放饵料和配件。如果钓到大鱼，可以直接放钓箱里加冰袋保温，不用鱼护。箱内有隔板可以分区，东西不会乱。成色8.5新，容量充足。', '钓箱,鱼护,容量,分区,装备' AS tags, '钓箱容量与鱼护放置说明' AS source_summary, 83
  UNION ALL SELECT 'sports_fishing', '鱼竿有竿袋吗？方便携带吗？', '亲，这款达瓦鱼竿配原装竿袋，加厚海绵内衬防震保护。3.6米收缩后1.05米，装竿袋后可以背在身上或者放后备箱。竿袋有提手和背带两种携带方式，很方便。竿袋是黑色防水面料，下雨也不怕。我每次钓鱼都背竿袋出门，很省心。成色9新，竿袋完好。', '鱼竿,竿袋,携带,收缩,防水' AS tags, '鱼竿竿袋与便携性说明' AS source_summary, 82
  UNION ALL SELECT 'sports_fishing', '鱼线能用多久？什么时候该换？', '亲，尼龙鱼线正常使用半年到1年建议更换。判断是否换线：1.线卷曲严重理不直；2.线变色发黄不透明；3.线变硬没有弹性；4.拉力明显下降容易断。我这条用了半年，状态还很好，强度90%以上。如果经常挂底或者钓大鱼，建议每3个月换一次。成色9新。', '鱼线,寿命,更换,判断,尼龙' AS tags, '鱼线寿命与更换判断说明' AS source_summary, 80
  UNION ALL SELECT 'sports_fishing', '这套钓具能便宜点吗？打包收吗？', '亲，鱼竿200、渔轮180、钓箱120、鱼线30、鱼钩10、鱼饵15，单买总价555。如果您打包一起收，给您优惠价480包邮，相当于8.7折。钓具都是9成新，品质很好，这套配齐基本钓鱼全覆盖了。打包出对我也省心，对您也划算。诚心要的话460给您，再送几个小配件。', '钓具,打包,优惠,套装,议价' AS tags, '钓具打包优惠与议价说明' AS source_summary, 86
  UNION ALL SELECT 'sports_fishing', '鱼竿是软调还是硬调？适合什么钓法？' AS question, '亲，这款达瓦是37调中硬竿，介于软调和硬调之间。软调28适合钓小鱼护线，硬调46适合钓大鱼控鱼。37调综合性能好，鲫鱼鲤鱼都能钓，是最百搭的调性。我钓过10斤鲤鱼没断竿，遛鱼3分钟上岸。新手建议选37调，操作容易不容易断线。成色9新。', '鱼竿,调性,37调,中硬,百搭' AS tags, '鱼竿调性与钓法适用说明' AS source_summary, 85
  UNION ALL SELECT 'sports_fishing', '渔轮能左手摇吗？可以改装吗？', '亲，这款禧玛诺渔轮默认是右手摇，但可以改装成左手摇。把摇柄拆下来装到另一侧就行，不需要工具，1分钟搞定。我发货时可以把摇柄装在您需要的一侧。左右手切换不影响渔轮性能。如果您是左撇子，记得告诉我，我帮您改装好再发。成色9新，改装方便。', '渔轮,左手,改装,摇柄,左右手' AS tags, '渔轮左右手改装说明' AS source_summary, 82
  UNION ALL SELECT 'sports_fishing', '钓箱有背带吗？背着累吗？', '亲，这款连球钓箱配原装背带，加宽海绵垫肩，背着一整天钓鱼也不会勒肩膀。背带是尼龙材质，承重20kg没问题。背带可以拆卸，不用时取下放箱里。钓箱自重只有1.8kg，加上装备约5kg，背着不累。两侧有提手，短距离搬运也方便。成色8.5新，背带完好。', '钓箱,背带,肩垫,便携,重量' AS tags, '钓箱背带与便携性说明' AS source_summary, 83
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
